"""Publish scoped full-wave improvement, independent validation and usage."""
import argparse,json
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from analyze_model_errors import read,z
from build_model_error_report import table

def pct(v):return f'{100*v:.4f}%'
def main(root):
    w=root/'work/maxwell-refinement';out=root/'outputs/differt-bridge/examples/maxwell_refinement';out.mkdir(parents=True,exist_ok=True)
    r=read(w/'analysis.json');g={(a['profile'],a['name']):a for a in r['comparisons']};rows=r['refinement'];names=[a['name'] for a in rows]
    plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False,'figure.dpi':160})
    fig,ax=plt.subplots(figsize=(12,5));x=np.arange(8)
    ax.bar(x-.2,[100*g['sionna-reciprocal',n]['total_complex_rms'] for n in names],.38,label='Reciprocal ray baseline (Sionna; DiffeRT agrees closely)',color='#8c9eae')
    ax.bar(x+.2,[100*a['total_complex_rms'] for a in rows],.38,label='Separate full-wave 2D field',color='#148d99')
    ax.set_yscale('log');ax.set_ylim(.01,10);ax.set_yticks([.01,.1,1,10],['0.01','0.1','1','10']);ax.set_xticks(x,[n.replace('_','\n') for n in names]);ax.set_ylabel('Complex RMS error to independent FDFD (%) • log scale');ax.set_title('Actual improvement in the declared 2D solid-wedge comparison');ax.legend();ax.grid(axis='y',alpha=.2);fig.tight_layout();fig.savefig(out/'improvement.png');plt.close(fig)
    fig,axs=plt.subplots(2,1,figsize=(11,6.5));a=g['sionna-reciprocal','concrete_Hz'];e=[v for v in a['entries'] if v['source']==4];angles=[v['angle_deg'] for v in e];b=z([v['prediction'] for v in e]);h=z([v['refined'] for v in e]);ref=z([v['reference'] for v in e])
    for u,label,color in [(ref,'Independent FDFD','#213a4c'),(b,'Ray approximation','#9d9a91'),(h,'Full-wave 2D','#148d99')]:axs[0].plot(angles,20*np.log10(abs(u)),label=label,color=color)
    axs[0].set(ylabel='Field magnitude (dB re unit source)',title='Concrete / Hz • source 252° nominal • identical measured receiver positions');axs[0].legend()
    axs[1].plot(angles,np.rad2deg(np.angle(h/ref)),color='#148d99');axs[1].axhline(0,color='gray',lw=.6);axs[1].set(xlabel='Receiver angle around the exterior (degrees)',ylabel='Refined phase error (degrees)',ylim=(-1,1),title='Magnified phase residual after refinement')
    for ax in axs:ax.grid(alpha=.2)
    fig.tight_layout();fig.savefig(out/'fields.png');plt.close(fig)
    results=[];phases=[];policies=[]
    for a in rows:
        name=a['name'];before=g['sionna-reciprocal',name]['total_complex_rms'];d=g['differt-reciprocal',name]['total_complex_rms']
        results.append([name,pct(before),pct(d),pct(a['total_complex_rms']),f'{before/a["total_complex_rms"]:.1f}×'])
        phases.append([name,f'{a["p95_abs_gain_db"]:.4f}',f'{np.rad2deg(a["p95_abs_phase_rad"]):.4f}',f'{a["phase_mask_samples"]}/265',pct(a['raw_forward_rms']),pct(a['raw_reverse_rms'])])
        policies.append([name,pct(before),pct(a['physical_optics_rms']),pct(a['total_complex_rms'])])
    convergence=[[a['name'],pct(a['grid60_to80']),pct(a['extrapolation_change']),pct(next(b['coarse_to_fine'] for b in rows if b['name']==a['name']))] for a in r['reference_checks']]
    boundary=read(w/'boundary.json')['results'];runtime=read(out/'reciprocal_blender.json');native=read(root/'outputs/differt-bridge/validation/workflow_health.json')
    page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Validated 2D Maxwell refinement</title><style>
    body{font:17px/1.6 system-ui;color:#203342;background:#f5f7fa;max-width:1160px;margin:auto;padding:32px}h1{font-size:40px;line-height:1.2}h2{margin-top:2.2em}a{color:#126e88}.callout{background:white;padding:24px;border-radius:12px;border-left:5px solid #148d99}video,img{width:100%;border-radius:8px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:10px;border-bottom:1px solid #dae2e8;text-align:left}th{background:#e6eef3}.scroll{overflow-x:auto}code,pre{background:#e6eef3;padding:4px}pre{padding:16px;overflow-x:auto}.muted{color:#566b79}li{margin:8px 0}</style></head><body>
    <p><a href="../../../../index.html">All results</a> / <a href="../diffraction_model_errors/index.html">Previous model-error investigation</a></p>
    <h1>Reducing the remaining Maxwell error</h1><p class="muted">7 November 2026 • Optional 2D field refinement • Native Sionna and DiffeRT retained</p>
    <div class="callout"><strong>The new full-wave 2D mode measures 0.018–0.050% complex RMS error, compared with 2.4–4.5% for the reciprocal ray model.</strong> The improvement comes from solving the coupled dielectric-face transmission problem. It is a separate line-source field calculation for a strictly supported canonical wedge; it does not change native UTD coefficients or claim general 3D accuracy.</div>
    <h2>Regenerated side-by-side animation</h2><video controls preload="metadata" poster="previews/frame_0361.png"><source src="Sionna_vs_DiffeRT_2D_Refinement.mp4" type="video/mp4"></video>
    <p><a href="Sionna_vs_DiffeRT_2D_Refinement.mp4">60-second MP4</a> · <a href="Maxwell_Refinement_Animation.blend">Blender timeline</a> · <a href="video_validation.json">Decode/reopen check</a> · <a href="animation_validation.json">Frame provenance</a></p>
    <p>The white curve is the independent FDFD reference, the colored curve is the labelled mode, and gray shows the reciprocal ray baseline. The identical refined curves in the two panels come from the <strong>shared full-wave solver</strong>, not two independent native engine improvements. Original engine paths remain visible. Phase plots explicitly change from ±45° for the baseline to ±1° for the refined field. The RMS label covers 265 channels per material/polarization; each moving plot shows one source. Lines connect measured receiver samples without synthesizing new physics values.</p>
    <h2>What actually reduced the error</h2><p>The earlier fixes corrected conventions, reciprocity and boundaries, but still used a local high-frequency diffraction approximation. Here, boundary fields and normal fluxes are solved together on both dielectric faces. Those currents radiate the total exterior field through a boundary-integral representation. No angle fit, material fit, reference-field lookup or trained correction is used.</p>
    <p>The boundary-integral implementation previously used as a reference is now the <strong>model under test</strong>. Its accuracy is checked against the separate finite-difference differential operator, never against itself. Both implementations are project code, so this is cross-formulation numerical validation rather than third-party certification.</p>
    <img src="improvement.png" alt="Log-scale before and after errors for all eight material-polarization groups">'''
    page+=table(['Group','Sionna reciprocal ray','DiffeRT reciprocal ray','Separate full-wave 2D','RMS reduction vs Sionna'],results)
    page+='''<p>RMS means ‖u − u<sub>FDFD</sub>‖₂ / ‖u<sub>FDFD</sub>‖₂ over the complete group. It is not a worst-link bound. This new port set is snapped to a common 0.05-wavelength lattice for consistent FDFD convergence; the table compares before and after on exactly that same nominal set. Engine float32 port storage introduces only sub-micrometre rounding at λ=1 m.</p>
    <h2>Remaining magnitude and phase error</h2><img src="fields.png" alt="Field magnitude and magnified phase error after full-wave refinement">'''
    page+=table(['Group','P95 |gain| dB','P95 |phase| °','Above −40 dB mask','Raw forward RMS','Raw reverse RMS'],phases)
    page+='''<p>Percentiles above include every channel; masked versions are also in the raw analysis. The mask retains reference amplitude above 1% of the group maximum. Weak/null channels remain sensitive to small absolute field errors, and the full-wave result still has a finite panel-discretization error. The refinement is an accuracy improvement, not exact arithmetic or an exact closed-form solution.</p>
    <h2>Independent Maxwell validation</h2><p>Fresh FDFD runs use 40, 60 and 80 cells per wavelength for all four materials and both polarizations (24 operators), plus two enlarged-PML controls (26 operators total). The unchanged FDFD implementation retains the earlier analytic free-space and exact PEC-wedge controls. The BIE uses 24 panels per exterior wavelength, checked against a 16-panel run. Each group contains five sources and 53 receivers.</p>'''
    page+=table(['Group','FDFD 60→80 change','Successive extrapolation change','BIE 16→24 change'],convergence)
    page+=f'''<p>The largest successive Richardson-estimate change is {pct(max(a['extrapolation_change'] for a in r['reference_checks']))}; enlarged PML changes are below {max(a['relative_change'] for a in r['pml_controls']):.3g} relative RMS. Raw finest-grid fields are also retained: Richardson estimates reduce the leading grid dispersion/interpolation error. These measured convergence indicators are not rigorous error bounds for individual links. They are substantially below the 0.1% total-RMS acceptance threshold used for this scoped mode.</p>
    <h2>Reciprocity and boundary behavior</h2><p>Constant-panel collocation has a small source/probe asymmetry. The mode independently solves both directions and takes (G<sub>forward</sub> + G<sub>reverse</sub><sup>T</sup>)/2, using the known Lorentz reciprocity of the declared scalar medium. There is no complex conjugation. This numerical symmetry projection is explicit: both unprojected fields, their FDFD errors and the raw reciprocity discrepancy are retained. Accuracy is already improved in both raw directions; averaging is not what produces the large error reduction.</p>'''
    page+=table(['Boundary control','Full-wave RMS to independent FDFD','Small-offset triplet span / max field'],[[a['name'],pct(a['rms_error']),pct(a['small_offset_triplet_span'])] for a in boundary])
    page+='''<p>These are the preceding near/exact GO-boundary probe positions, now evaluated by the full-wave mode. Its total field has no GO-presence switch; the small triplet span measures a smooth sampled variation, not an asserted mathematical zero jump. Native 3D exact-boundary and mixed-path corrections remain unchanged.</p>
    <h2>Why not use a cheaper face-current approximation?</h2><p>An uncoupled physical-optics diagnostic uses local Fresnel face fields and radiates their equivalent currents, with the same reciprocal projection. It improves several cases but regresses others, including absorbing Ez and higher-permittivity Ez:</p>'''
    page+=table(['Group','Reciprocal ray','Uncoupled face-current diagnostic','Coupled full-wave 2D'],policies)
    page+='''<p>The uncoupled diagnostic is therefore not adopted. It is our numerical diagnostic, not a claimed reproduction of a published UAPO/EPO coefficient. The physical motivation for testing coupled currents is supported by primary dielectric-wedge work: <a href="https://globals.ieice.org/en_transactions/electronics/10.1587/transele.2023ECP5027/_f">Nguyen, Shirai and Kim (2024)</a> derive equivalent-current fields and discuss the limits of approximate currents at dielectric boundaries. We instead solve the declared transmission problem numerically.</p>
    <h2>Scope guards: obstacles cannot disappear</h2><p>The refinement requires an explicit <code>maxwell_domain</code> declaration and validates the entire batch before computing. It accepts only the specified solid 90° lossy wedge, broadside Ez or Hz line sources, isotropic ports, λ=1 m, ports within the validated 5-wavelength box and at least 0.75 wavelengths from the corner. The material envelope is 1 &lt; Re(ε) ≤ 10 and 0.1 ≤ −Im(ε) ≤ 10; accuracy claims still refer to the tested materials, not every value in that envelope.</p>
    <p>Extra obstacles, modified triangles, rotated/skew geometry, point-source domains, arrays, cross polarization, finite slabs, multiple interactions and zero-loss materials are rejected. A tiny-obstacle batch test verifies rejection before the solver is called. No obstacle is dropped and no unsupported scene is silently treated as refined. Use the native/reciprocal Blender ray workflow for general 3D scenes.</p>
    <h2>Use the new comparison mode</h2><p>Run <a href="../../../../Compare_Maxwell_Wedge.ps1">Compare_Maxwell_Wedge.ps1</a>. It runs both configured engines and writes unmodified ray results plus separate <code>refinement.json</code> and <code>comparison.json</code> files under <code>work/canonical-maxwell-comparison</code>. Optional <code>-Manifest</code> and <code>-Output</code> arguments support another explicitly valid canonical input. This is a companion comparison command, not a new Blender simulation setting.</p>
    <p>The validated integration run preserves every engine-result hash. Its full-wave field is shared between the Sionna and DiffeRT comparison records. The 24-panel, eight-group field solves took approximately 97 seconds on this run, excluding initial operator setup and ray tracing; this is a larger calculation than a local UTD coefficient and is not a general large-scene acceleration.</p>
    <p>The existing <a href="../../../../Launch_Diffraction.ps1">native</a> and <a href="../../../../Launch_Reciprocal_Diffraction.ps1">reciprocal</a> Blender launchers remain available. The movie timeline is portable and uses a relative MP4 path; it is not an editable full-wave simulation scene. <a href="../../../../Regenerate_Refinement_Animation.ps1">Regenerate_Refinement_Animation.ps1</a> redraws validated data and encodes the film.</p>'''
    page+=f'''<h2>Verification and reproducible evidence</h2><ul><li>160 fresh engine fixture executions, 8,480 ray-channel comparisons and 2,120 full-wave channels.</li><li>33 analytic/model/guard tests passed. Source and runtime protection checks cover 79 files plus 14 optional-profile helpers.</li><li>Fresh native Blender comparison: {native['blender']['comparison']['matched_paths']} matched paths, {native['blender']['comparison']['maximum_phase_difference_rad']} exported phase gap.</li><li>Fresh reciprocal Blender comparison: {runtime['counts']['matched']} matched paths; both external worker activations and preferences verified.</li></ul>'''
    page+='''<p><a href="refinement_evidence.zip">Source, raw fields, receipts and reproduction commands</a> · <a href="verification.json">Verification record</a> · <a href="checksums.sha256">Checksums</a> · <a href="reciprocal_blender.json">Reciprocal Blender receipt</a> · <a href="../../validation/workflow_health.json">Native workflow receipt</a></p>
    <p class="muted">Historical reports and animations remain available. The remaining task for a general ray-tracing physics upgrade is a transmission-aware 3D point-source model with independent 3D Maxwell validation; this scoped 2D mode does not establish that result.</p></body></html>'''
    (out/'index.html').write_text(page,encoding='utf-8',newline='\n')
    print('REFINEMENT_REPORT_BUILT',out,flush=True)

if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('root',type=Path);a=ap.parse_args();main(a.root.resolve())
